17. 다음 C 코드에서 heapify(a, 7)을 수행한 후 배열 a[]의 내용은?
(단, 모든 배열 원소값은 양의 정수로 한정하고, －1은 연산 대상이
아니며, 0은 삭제된 값을 나타낸다)
int a[8]={-1, 1, 2, 3, 6, 4, 7, 5};
int heapify(int *a, int n) {
int item=a[1], temp=a[n];
int i=1, j=2;
a[n]=0, n=n-1;
while(j<=n) {
if(j<n && a[j]>a[j+1]) j++;
if(temp<a[j]) break;
else {
a[i]=a[j];
i=j;
j=j*2;
}
}
a[i]=temp;
return item;
}
0 1 2 3 4 5 6 7

